// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));

        BankHelper bank = new BankHelper();

        vm.deal(caller, 1 ether);

        address helperAddr = address(bank);
        vm.assume(c.tokenBalance(helperAddr) == 0);

        bank.callAirDrop(address(c));

        assertTrue(c.tokenBalance(helperAddr) == 20);
    }
}

contract BankHelper {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }

    function callAirDrop(address cAddr) external {
        ModifierEntrancy(cAddr).airDrop();
    }
}
